FROM (VALUES
  ('g-kentei-c-q31', '{"viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect width=\"340\" height=\"140\" fill=\"#0b0f1a\"/><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.3\" text-anchor=\"middle\" font-weight=\"600\">同じ「人」でも個体ごとに色を分けるか</text><text x=\"85\" y=\"34\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">セマンティックセグメンテーション</text><circle cx=\"55\" cy=\"68\" r=\"14\" fill=\"#60a5fa\" opacity=\"0.7\"/><circle cx=\"85\" cy=\"73\" r=\"14\" fill=\"#60a5fa\" opacity=\"0.7\"/><circle cx=\"115\" cy=\"68\" r=\"14\" fill=\"#60a5fa\" opacity=\"0.7\"/><text x=\"85\" y=\"102\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">全員「人」で同じ色</text><line x1=\"170\" y1=\"26\" x2=\"170\" y2=\"116\" stroke=\"#2a2f3f\"/><text x=\"255\" y=\"34\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">インスタンスセグメンテーション</text><circle cx=\"225\" cy=\"68\" r=\"14\" fill=\"#60a5fa\" opacity=\"0.7\"/><circle cx=\"255\" cy=\"73\" r=\"14\" fill=\"#6ab08d\" opacity=\"0.7\"/><circle cx=\"285\" cy=\"68\" r=\"14\" fill=\"#e3b341\" opacity=\"0.7\"/><text x=\"255\" y=\"102\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">1人目・2人目・3人目で別の色</text><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">画素の塗り分け＋個体の区別まで行うのがインスタンス</text></svg>"}'::jsonb),
  ('g-kentei-d-q13', '{"viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect width=\"340\" height=\"140\" fill=\"#0b0f1a\"/><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.3\" text-anchor=\"middle\" font-weight=\"600\">カテゴリごとに1か所だけ1にする</text><text x=\"40\" y=\"42\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"start\">赤</text><rect x=\"70\" y=\"30\" width=\"26\" height=\"20\" fill=\"#3b82f6\" opacity=\"0.85\"/><text x=\"83\" y=\"44\" fill=\"#0b0f1a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">1</text><rect x=\"100\" y=\"30\" width=\"26\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"113\" y=\"44\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0</text><rect x=\"130\" y=\"30\" width=\"26\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"143\" y=\"44\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0</text><text x=\"40\" y=\"72\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"start\">青</text><rect x=\"70\" y=\"60\" width=\"26\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"83\" y=\"74\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0</text><rect x=\"100\" y=\"60\" width=\"26\" height=\"20\" fill=\"#3b82f6\" opacity=\"0.85\"/><text x=\"113\" y=\"74\" fill=\"#0b0f1a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">1</text><rect x=\"130\" y=\"60\" width=\"26\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"143\" y=\"74\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0</text><text x=\"40\" y=\"102\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"start\">緑</text><rect x=\"70\" y=\"90\" width=\"26\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"83\" y=\"104\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0</text><rect x=\"100\" y=\"90\" width=\"26\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"113\" y=\"104\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0</text><rect x=\"130\" y=\"90\" width=\"26\" height=\"20\" fill=\"#3b82f6\" opacity=\"0.85\"/><text x=\"143\" y=\"104\" fill=\"#0b0f1a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">1</text><text x=\"235\" y=\"65\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">どの色も、あてはまる</text><text x=\"235\" y=\"78\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">1か所だけ1、他は0</text><text x=\"170\" y=\"128\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">大小関係のない項目に余計な順序を持ち込まない</text></svg>"}'::jsonb)
